'use server'

import { updateTag } from 'next/cache'
import { savePost } from '../lib/posts'

export async function createPost(formData: FormData): Promise<void> {
  const title = String(formData.get('title') ?? '').trim()
  const body = String(formData.get('body') ?? '').trim()

  if (!title || !body) {
    throw new Error('A title and body are required.')
  }

  await savePost(title, body)
  updateTag('posts')
}
import { randomUUID } from 'node:crypto'
import { unstable_cache } from 'next/cache'

export type Post = {
  id: string
  title: string
  body: string
  createdAt: string
}

// This starter has no database configured. Keep records in the server process
// so the create flow can be exercised; replace these functions with the
// application's persistent data layer when one is available.
let posts: Post[] = []

async function readPosts(): Promise<Post[]> {
  return posts.toSorted((a, b) => b.createdAt.localeCompare(a.createdAt))
}

export const getPosts = unstable_cache(readPosts, ['posts'], {
  tags: ['posts'],
})

export async function savePost(title: string, body: string): Promise<void> {
  posts = [
    {
      id: randomUUID(),
      title,
      body,
      createdAt: new Date().toISOString(),
    },
    ...posts,
  ]
}
